def get_weather(city: str) -> dict:
    """Return the current weather for ``city`` as a structured dict.

    Args:
        city: City name; whitespace is stripped and the name is title-cased.

    Returns:
        dict: the weather reading, or an ``error`` key when the input is invalid.
    """
    if not isinstance(city, str):
        return {"error": "city must be a non-empty string"}
    normalised = city.strip()
    if normalised == "":
        return {"error": "city must be a non-empty string"}
    return {
        "city": normalised.title(),
        "temperature_c": 21.0,
        "conditions": "sunny",
        "source": "stub",
    }
